public String longestPalindrome(String s) {
    int n = s.length();
    String best = "";
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (isPalindrome(s, i, j) && j - i + 1 > best.length()) {
                best = s.substring(i, j + 1);
            }
        }
    }
    return best;
}

private boolean isPalindrome(String s, int lo, int hi) {
    while (lo < hi) {
        if (s.charAt(lo) != s.charAt(hi)) return false;
        lo++;
        hi--;
    }
    return true;
}

