def longestPalindrome(self, s: str) -> str:
    n = len(s)
    best = ""
    for i in range(n):
        for j in range(i, n):
            if j - i + 1 > len(best) and self._is_pal(s, i, j):
                best = s[i:j + 1]
    return best

def _is_pal(self, s: str, lo: int, hi: int) -> bool:
    while lo < hi:
        if s[lo] != s[hi]:
            return False
        lo += 1
        hi -= 1
    return True

