def longestPalindrome(self, s: str) -> str:
    if not s:
        return ""
    start, max_len = 0, 1

    def expand(l: int, r: int) -> int:
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1

    for i in range(len(s)):
        length = max(expand(i, i), expand(i, i + 1))
        if length > max_len:
            start = i - (length - 1) // 2
            max_len = length
    return s[start:start + max_len]

